// pauseWithdraw :596-611 -- no _updatePool() above, no _updatePhUSDEmissionRate() below
function pauseWithdraw(uint256 amount) external whenPaused {
    UserInfo storage user = userInfo[msg.sender];
    require(user.amount >= amount, "Insufficient balance");
    require(amount > 0, "Amount must be greater than 0");

    user.amount -= amount;
    totalStaked -= amount;          // <-- rate NOT resized

    user.phUSDDebt = (user.amount * accPhUSDPerShare) / PRECISION;
    user.stableDebt = (user.amount * accStablePerShare) / PRECISION;
    user.promoDebt = (user.amount * accPromoPerShare) / PRECISION;

    IERC20(address(phUSD)).safeTransfer(msg.sender, amount);
    emit EmergencyWithdrawal(msg.sender, amount);
}

// _updatePool :803-806 -- stale numerator over shrunken denominator
if (phUSDPerSecond > 0) {
    uint256 phUSDReward = timeElapsed * phUSDPerSecond;   // sized for S0
    accPhUSDPerShare += (phUSDReward * PRECISION) / totalStaked;  // now S1
}

// _claimRewards :851-854 -- the excess is MINTED, not paid from a balance
uint256 pendingPhUSDAmount = (userDetails.amount * accPhUSDPerShare) / PRECISION - userDetails.phUSDDebt;
if (pendingPhUSDAmount > 0) {
    phUSD.mint(beneficiary, pendingPhUSDAmount);
}

function collectReward(uint256 amount) external nonReentrant {
    require(amount > 0, "Amount must be greater than 0");   // 1 wei passes
    _updatePool();
    rewardToken.safeTransferFrom(msg.sender, address(this), amount);
    rewardBalance += amount;
    // Recalculate rate based on new balance -- this is the canonical recompute site.
    rewardPerSecond = (rewardBalance * PRECISION) / depletionDuration;   // :629 fresh full window
    emit RewardCollected(amount, rewardBalance, rewardPerSecond);
}

// :322-323 docblock -- an UNCONDITIONAL claim
//   A RETIRED token's bank (promoToken == address(0) for it) is unreachable here
//   and stays pullable via `claimUnclaimablePromo`.

// :335-340 -- but 'retired' is not a property of the bank, it is a property of the SLOT
if (address(promoToken) != address(0)) {
    uint256 promoBalance = promoToken.balanceOf(address(this));
    if (promoBalance > 0) {
        promoToken.safeTransfer(recipient, promoBalance);   // sweeps the OLD bank too
    }
}

// :356 -- nothing stops re-promoting a token that still owes a bank
require(token != address(0) && token != address(phUSD) && token != address(rewardToken), "Invalid promo token");
